def transform(grid):
    h, w = len(grid), len(grid[0])
    # The examples contain two aligned panels separated by a solid line.
    for r in range(h):
        if len(set(grid[r])) == 1:
            top, bottom = grid[:r], grid[r + 1:]
            if top and len(top) == len(bottom) and all(len(x) == len(y) for x, y in zip(top, bottom)):
                return _overlap(top, bottom)
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if left and len(left[0]) == len(right[0]):
                return _overlap(left, right)
    raise ValueError('aligned panels and solid divider not found')

def _overlap(a, b):
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    if len(shared) != 1:
        raise ValueError('expected one shared color')
    color = next(iter(shared))
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(len(a[r]))] for r in range(len(a))]
